export const meta = {
  name: 'ebc-build-3',
  description: 'eBook Cadeau build unit: implement crate(s) -> two sparring reviewers (break it / check it against the domain) -> fix -> verify',
  phases: [
    { title: 'Implement', detail: 'one implementer per unit, owns its crate directories' },
    { title: 'Spar', detail: 'two independent reviewers per unit: breaker + domain auditor' },
    { title: 'Fix', detail: 'implementer-side fixer applies confirmed findings' },
    { title: 'Verify', detail: 'fresh agent re-runs every check and reports honestly' },
  ],
}

const ROOT = '/home/user/ebook-cadeau'
const COMMON = `
You are working on "eBook Cadeau" in ${ROOT} (a Rust workspace). FIRST read ${ROOT}/CLAUDE.md and ${ROOT}/docs/architecture.md
(sections 1-4, and in section 5 the contract of your crate(s) and of the crates you depend on), then the sources of the crates you depend on
(crates/ebc-scene is the shared contract; crates/ebc-isbn and crates/ebc-model hold contract types).
Other agents are building sibling crates in the same working tree right now: touch ONLY your own directories, never run git, add dependencies
only with \`cargo add -p <your-crate> ...\`, and build/test only with \`-p <your-crate>\`. Cargo may block on the build-directory lock — wait (use
Bash timeouts up to 600000 ms). Third-party crate sources are readable under ~/.cargo/registry/src/ once fetched (docs.rs is not reachable).
Research documents may appear under ${ROOT}/docs/research/*.md while you work — if the one relevant to you exists, read it and follow its
"Implications for the implementation" section; if it does not exist yet, use well-established defaults and note the assumption.
`

const DONE = `
DEFINITION OF DONE (run all of these yourself and paste the tail of each output in your report):
  cargo fmt -p <crate>            (for each of your crates)
  cargo build -p <crate>
  cargo test -p <crate>
  cargo clippy -p <crate> --all-targets -- -D warnings
  cargo build -p <crate> --target wasm32-unknown-unknown      (library crates that must be wasm-compatible)
Tests must be offline, deterministic and meaningful (behaviour, edge cases, hostile input), not smoke tests.
FINAL REPORT: public API summary, deviations from the contract in docs/architecture.md (with reasons), assumptions, known limitations
(be candid — anything stubbed or approximate must be listed), and the number of tests.
`

